//! Staging helper for execution jobs (shell/browser/backend).
//!
//! A job stages the explicitly scoped workspace subtree into its execution
//! environment with [`stage_subtree`] (bytes stream through the sealed
//! artifact store via `attachments::read`; metadata resolves paths so
//! user-supplied strings never become server paths), then imports the
//! result with [`diff_commit`].
//!
//! Import is one CAS diff-commit per file: each staged file carries its
//! baseline revision. If the owner edited a file while the job ran, the
//! generated bytes are preserved under `Outputs` (unique name, never a
//! silent overwrite of the owner's new version) and the commit returns
//! `WORKSPACE_CONFLICT`. Files the owner did not touch still commit.
//! Never copies the whole server home: only the staged subtree is
//! materialized.

use std::collections::{BTreeMap, BTreeSet};
use std::path::{Path, PathBuf};

use orbit_core::{Error, OwnerScope, Result};
use sha2::{Digest, Sha256};
use sqlx::{PgPool, Row};
use uuid::Uuid;

use crate::{EntryKind, WorkspaceEntry};

/// Hard caps so a hostile or runaway job cannot stage unbounded state.
pub const MAX_STAGED_FILES: usize = 2000;
pub const MAX_STAGE_BYTES: u64 = 50 * 1024 * 1024;
pub const MAX_NEW_FILES: usize = 500;
/// Sealed-byte ceiling inherited from `attachments` (10 MiB).
const MAX_FILE_BYTES: usize = 10 * 1024 * 1024;

/// One staged file with the baseline it must CAS against on import.
pub struct StagedFile {
    pub entry_id: Uuid,
    pub rel_path: String,
    pub baseline_revision: i64,
    pub baseline_artifact: Option<Uuid>,
    pub baseline_sha256: Option<String>,
}

/// Materialized subtree. Owns the tempdir; dropping it removes staged bytes.
pub struct StagedTree {
    pub dir: tempfile::TempDir,
    pub root_entry: Uuid,
    pub files: Vec<StagedFile>,
    /// Directory rel-path (`""`, `"a"`, `"a/b"`) to workspace entry id.
    pub dirs: BTreeMap<String, Uuid>,
}

impl StagedTree {
    pub fn path(&self) -> &Path {
        self.dir.path()
    }
}
/// Owner-scoped entry fetch by id. Foreign ids are `NotFound` (404).
async fn entry_by_id(pool: &PgPool, scope: &OwnerScope, id: Uuid) -> Result<WorkspaceEntry> {
    sqlx::query_as::<_, WorkspaceEntry>(
        "SELECT id, owner_id, parent_id, name, kind, head_artifact_id, revision, trashed_at, created_at, updated_at
         FROM workspace_entries WHERE owner_id = $1 AND id = $2",
    )
    .bind(scope.owner_id)
    .bind(id)
    .fetch_optional(pool)
    .await?
    .ok_or(Error::NotFound)
}


fn sha256hex(bytes: &[u8]) -> String {
    hex::encode(Sha256::digest(bytes))
}

/// Materialize the directory `entry_id` (owner-scoped) into a tempdir.
/// File bytes stream via `attachments::read`, so mount provenance, SECRET
/// rejection and digest checks apply exactly as for owner reads.
pub async fn stage_subtree(
    pool: &PgPool,
    artifact_root: &Path,
    scope: &OwnerScope,
    entry_id: Uuid,
) -> Result<StagedTree> {
    let root = entry_by_id(pool, scope, entry_id).await?;
    if root.entry_kind()? != EntryKind::Directory {
        return Err(Error::Validation("entry is not a directory".into()));
    }
    if root.is_trashed() {
        return Err(Error::Validation("entry is trashed".into()));
    }
    let dir =
        tempfile::TempDir::new().map_err(|_| Error::Unavailable("staging unavailable".into()))?;
    let mut tree = StagedTree {
        dir,
        root_entry: root.id,
        files: Vec::new(),
        dirs: BTreeMap::from([(String::new(), root.id)]),
    };
    let mut total: u64 = 0;
    let mut stack: Vec<(WorkspaceEntry, String)> = vec![(root, String::new())];
    while let Some((entry, rel)) = stack.pop() {
        let staged_dir = tree.dir.path().join(Path::new(&rel));
        tokio::fs::create_dir_all(&staged_dir)
            .await
            .map_err(|_| Error::Unavailable("staging unavailable".into()))?;
        // Full listing under the 100-row page cap.
        let mut cursor: Option<Uuid> = None;
        loop {
            let page = crate::children(pool, scope, &entry, 100, cursor).await?;
            if page.is_empty() {
                break;
            }
            let last = page.last().map(|e| e.id);
            for kid in &page {
                let rel_path = if rel.is_empty() {
                    kid.name.clone()
                } else {
                    format!("{rel}/{}", kid.name)
                };
                if rel_path.len() > 1024 {
                    return Err(Error::Validation("staged path too deep".into()));
                }
                match kid.entry_kind()? {
                    EntryKind::Directory => {
                        tree.dirs.insert(rel_path.clone(), kid.id);
                        stack.push((kid.clone(), rel_path));
                    }
                    EntryKind::File => {
                        if tree.files.len() >= MAX_STAGED_FILES {
                            return Err(Error::Validation("subtree exceeds staging bound".into()));
                        }
                        let (baseline_sha256, baseline_artifact) =
                            match kid.head_artifact_id {
                                Some(aid) => {
                                    let (_name, bytes, _source) =
                                        orbit_agent_runtime::attachments::read(
                                            pool,
                                            artifact_root,
                                            scope,
                                            aid,
                                        )
                                        .await?;
                                    total += bytes.len() as u64;
                                    if total > MAX_STAGE_BYTES {
                                        return Err(Error::Validation(
                                            "subtree exceeds staging bound".into(),
                                        ));
                                    }
                                    let sha = sha256hex(&bytes);
                                    tokio::fs::write(tree.dir.path().join(Path::new(&rel_path)), &bytes)
                                        .await
                                        .map_err(|_| {
                                            Error::Unavailable("staging unavailable".into())
                                        })?;
                                    (Some(sha), Some(aid))
                                }
                                None => (None, None),
                            };
                        tree.files.push(StagedFile {
                            entry_id: kid.id,
                            rel_path,
                            baseline_revision: kid.revision,
                            baseline_artifact,
                            baseline_sha256,
                        });
                    }
                }
            }
            if page.len() < 100 {
                break;
            }
            cursor = last;
        }
    }
    Ok(tree)
}

async fn artifact_mime(pool: &PgPool, scope: &OwnerScope, artifact_id: Uuid) -> String {
    sqlx::query("SELECT mime_type FROM artifacts WHERE owner_id=$1 AND id=$2")
        .bind(scope.owner_id)
        .bind(artifact_id)
        .fetch_optional(pool)
        .await
        .ok()
        .flatten()
        .and_then(|r| r.try_get::<String, _>("mime_type").ok())
        .unwrap_or_else(|| "application/octet-stream".into())
}

async fn head_sha256(pool: &PgPool, scope: &OwnerScope, entry: &WorkspaceEntry) -> Option<String> {
    let aid = entry.head_artifact_id?;
    sqlx::query("SELECT sha256 FROM artifacts WHERE owner_id=$1 AND id=$2")
        .bind(scope.owner_id)
        .bind(aid)
        .fetch_optional(pool)
        .await
        .ok()
        .flatten()
        .and_then(|r| r.try_get::<String, _>("sha256").ok())
}

/// Create with a bounded unique-name retry on collision.
async fn create_unique(
    pool: &PgPool,
    scope: &OwnerScope,
    parent: Uuid,
    name: &str,
    kind: EntryKind,
    artifact: Option<Uuid>,
) -> Result<WorkspaceEntry> {
    let stem: String = name.chars().take(200).collect();
    let mut last_err = Error::Conflict("name already exists".into());
    for i in 0..10 {
        let candidate = if i == 0 {
            stem.clone()
        } else {
            format!("{stem}.{i}")
        };
        match crate::create(pool, scope, parent, &candidate, kind, artifact).await {
            Ok(entry) => return Ok(entry),
            Err(Error::Conflict(_)) => {
                last_err = Error::Conflict("name already exists".into());
                continue;
            }
            Err(e) => return Err(e),
        }
    }
    Err(last_err)
}

/// Where conflicted generated bytes are preserved: `Outputs` when the lazy
/// seed exists, otherwise the staged root itself.
async fn preservation_parent(
    pool: &PgPool,
    scope: &OwnerScope,
    root_entry: Uuid,
) -> Uuid {
    match crate::resolve(pool, scope, &["Outputs".to_string()]).await {
        Ok(dir) => dir.id,
        Err(_) => root_entry,
    }
}

/// A file the owner changed mid-job, with its generated bytes preserved.
pub struct ConflictInfo {
    pub entry_id: Uuid,
    pub rel_path: String,
    pub preserved_entry_id: Uuid,
    pub preserved_name: String,
}

/// Outcome of [`diff_commit`]. Returned on success; when `preserved_conflicts`
/// is non-empty the function instead returns `Error::Conflict` carrying
/// `WORKSPACE_CONFLICT` (after committing everything committable).
pub struct DiffOutcome {
    pub updated: Vec<Uuid>,
    pub created: Vec<Uuid>,
    pub unchanged: usize,
    pub preserved_conflicts: Vec<ConflictInfo>,
}

impl DiffOutcome {
    pub fn had_conflicts(&self) -> bool {
        !self.preserved_conflicts.is_empty()
    }
}

struct PendingChange {
    entry_id: Uuid,
    baseline_revision: i64,
    bytes: Vec<u8>,
    name: String,
    head_mime: String,
}

struct PendingConflict {
    entry_id: Uuid,
    rel_path: String,
    name: String,
    bytes: Vec<u8>,
    mime: String,
}

/// CAS import of staged bytes back into the workspace.
///
/// * Unchanged files (staged sha matches baseline, or the owner's current
///   head) are skipped.
/// * Changed files whose current revision still equals the baseline commit
///   via `set_content` (new sealed artifact + version row).
/// * Files the owner touched (revision moved, trashed, or deleted) are
///   preserved as new files under `Outputs` and reported as conflicts.
/// * New files created by the job in the staged dir are imported (new
///   directories included), independent of conflicts elsewhere.
///
/// Post-state: committable files are durable and conflicted bytes are
/// preserved; if any conflict exists the return is
/// `Error::Conflict("WORKSPACE_CONFLICT: ...")`, never an overwrite of the
/// owner's newer version.
pub async fn diff_commit(
    pool: &PgPool,
    artifact_root: &Path,
    scope: &OwnerScope,
    staged: &StagedTree,
    _created_by_task_id: Option<Uuid>,
) -> Result<DiffOutcome> {
    let mut outcome = DiffOutcome {
        updated: Vec::new(),
        created: Vec::new(),
        unchanged: 0,
        preserved_conflicts: Vec::new(),
    };
    // Phase 1: classify without writing.
    let mut changes: Vec<PendingChange> = Vec::new();
    let mut conflicts: Vec<PendingConflict> = Vec::new();
    for file in &staged.files {
        let full = staged.path().join(Path::new(&file.rel_path));
        let bytes = match tokio::fs::read(&full).await {
            Ok(bytes) => bytes,
            Err(e) if e.kind() == std::io::ErrorKind::NotFound => continue,
            Err(_) => return Err(Error::Unavailable("staged file unreadable".into())),
        };
        if bytes.len() > MAX_FILE_BYTES {
            return Err(Error::Validation("staged file exceeds 10 MiB".into()));
        }
        if Some(sha256hex(&bytes)) == file.baseline_sha256 {
            outcome.unchanged += 1;
            continue;
        }
        let current = match entry_by_id(pool, scope, file.entry_id).await {
            Ok(entry) => entry,
            Err(Error::NotFound) => {
                conflicts.push(PendingConflict {
                    entry_id: file.entry_id,
                    rel_path: file.rel_path.clone(),
                    name: file
                        .rel_path
                        .rsplit('/')
                        .next()
                        .unwrap_or("staged")
                        .to_string(),
                    bytes,
                    mime: "application/octet-stream".into(),
                });
                continue;
            }
            Err(e) => return Err(e),
        };
        if current.is_trashed() || current.revision != file.baseline_revision {
            let mime = match current.head_artifact_id {
                Some(aid) => artifact_mime(pool, scope, aid).await,
                None => "application/octet-stream".into(),
            };
            conflicts.push(PendingConflict {
                entry_id: file.entry_id,
                rel_path: file.rel_path.clone(),
                name: current.name.clone(),
                bytes,
                mime,
            });
            continue;
        }
        // Owner converged on identical bytes independently: nothing to do.
        if let Some(current_sha) = head_sha256(pool, scope, &current).await {
            if current_sha == sha256hex(&bytes) {
                outcome.unchanged += 1;
                continue;
            }
        }
        let mime = match current.head_artifact_id {
            Some(aid) => artifact_mime(pool, scope, aid).await,
            None => "application/octet-stream".into(),
        };
        changes.push(PendingChange {
            entry_id: file.entry_id,
            baseline_revision: file.baseline_revision,
            bytes,
            name: current.name.clone(),
            head_mime: mime,
        });
    }
    // Phase 2: commit non-conflicted changes (a lost CAS race degrades to
    // a conflict instead of an overwrite).
    for change in changes {
        let stored = orbit_agent_runtime::attachments::upload(
            pool,
            artifact_root,
            scope,
            &change.name,
            &change.head_mime,
            &change.bytes,
        )
        .await?;
        let new_id: Uuid = stored
            .get("id")
            .and_then(|v| serde_json::from_value(v.clone()).ok())
            .ok_or_else(|| Error::Unavailable("upload identity unavailable".into()))?;
        match crate::set_content(pool, scope, change.entry_id, change.baseline_revision, new_id)
            .await
        {
            Ok(_) => outcome.updated.push(change.entry_id),
            Err(Error::Conflict(_)) => {
                let parent = preservation_parent(pool, scope, staged.root_entry).await;
                let preserved_name = format!(
                    "{}.generated-{}",
                    change.name.chars().take(200).collect::<String>(),
                    &Uuid::new_v4().simple().to_string()[..8]
                );
                let preserved =
                    create_unique(pool, scope, parent, &preserved_name, EntryKind::File, Some(new_id))
                        .await?;
                outcome.preserved_conflicts.push(ConflictInfo {
                    entry_id: change.entry_id,
                    rel_path: change.name.clone(),
                    preserved_entry_id: preserved.id,
                    preserved_name: preserved.name,
                });
            }
            Err(e) => return Err(e),
        }
    }
    // Phase 3: preserve owner-touched files under Outputs (never overwrite).
    if !conflicts.is_empty() {
        let parent = preservation_parent(pool, scope, staged.root_entry).await;
        for conflict in conflicts {
            let stored = orbit_agent_runtime::attachments::upload(
                pool,
                artifact_root,
                scope,
                &conflict.name,
                &conflict.mime,
                &conflict.bytes,
            )
            .await?;
            let new_id: Uuid = stored
                .get("id")
                .and_then(|v| serde_json::from_value(v.clone()).ok())
                .ok_or_else(|| Error::Unavailable("upload identity unavailable".into()))?;
            let preserved_name = format!(
                "{}.generated-{}",
                conflict.name.chars().take(200).collect::<String>(),
                &Uuid::new_v4().simple().to_string()[..8]
            );
            let preserved =
                create_unique(pool, scope, parent, &preserved_name, EntryKind::File, Some(new_id))
                    .await?;
            outcome.preserved_conflicts.push(ConflictInfo {
                entry_id: conflict.entry_id,
                rel_path: conflict.rel_path,
                preserved_entry_id: preserved.id,
                preserved_name: preserved.name,
            });
        }
    }
    // Phase 4: import job-created files (and directories), top-down.
    import_new_files(pool, artifact_root, scope, staged, &mut outcome).await?;
    if outcome.had_conflicts() {
        return Err(Error::Conflict(format!(
            "WORKSPACE_CONFLICT: {} file(s) changed by the owner during the job; generated content preserved under Outputs",
            outcome.preserved_conflicts.len()
        )));
    }
    Ok(outcome)
}

/// Walk the staged dir for paths the job created (not in the stage
/// manifest) and import them: new directories become directory entries,
/// new files are sealed via `attachments::upload` + `create`. Symlinks are
/// never followed or imported.
async fn import_new_files(
    pool: &PgPool,
    artifact_root: &Path,
    scope: &OwnerScope,
    staged: &StagedTree,
    outcome: &mut DiffOutcome,
) -> Result<()> {
    let known_files: BTreeSet<&str> = staged.files.iter().map(|f| f.rel_path.as_str()).collect();
    let mut dir_ids: BTreeMap<String, Uuid> = staged.dirs.clone();
    let mut new_files: Vec<(String, PathBuf)> = Vec::new();
    let mut stack: Vec<(PathBuf, String)> = vec![(staged.path().to_path_buf(), String::new())];
    while let Some((dir, rel)) = stack.pop() {
        let mut entries = tokio::fs::read_dir(&dir)
            .await
            .map_err(|_| Error::Unavailable("staged file unreadable".into()))?;
        while let Some(entry) = entries
            .next_entry()
            .await
            .map_err(|_| Error::Unavailable("staged file unreadable".into()))?
        {
            let file_type = entry
                .file_type()
                .await
                .map_err(|_| Error::Unavailable("staged file unreadable".into()))?;
            if file_type.is_symlink() {
                continue;
            }
            let name = entry.file_name().to_string_lossy().into_owned();
            if crate::validate_name(&name).is_err() {
                continue;
            }
            let child_rel = if rel.is_empty() {
                name.clone()
            } else {
                format!("{rel}/{name}")
            };
            if child_rel.len() > 1024 {
                return Err(Error::Validation("staged path too deep".into()));
            }
            if file_type.is_dir() {
                if !dir_ids.contains_key(&child_rel) {
                    let parent_rel = rel.clone();
                    let parent_id = dir_ids.get(&parent_rel).copied().ok_or_else(|| {
                        Error::Validation("staged parent directory unknown".into())
                    })?;
                    let created =
                        create_unique(pool, scope, parent_id, &name, EntryKind::Directory, None)
                            .await?;
                    dir_ids.insert(child_rel.clone(), created.id);
                }
                stack.push((entry.path(), child_rel));
            } else if file_type.is_file() {
                if !known_files.contains(child_rel.as_str()) {
                    if new_files.len() >= MAX_NEW_FILES {
                        return Err(Error::Validation("too many new staged files".into()));
                    }
                    new_files.push((child_rel, entry.path()));
                }
            }
        }
    }
    for (rel, full) in new_files {
        let bytes = tokio::fs::read(&full)
            .await
            .map_err(|_| Error::Unavailable("staged file unreadable".into()))?;
        if bytes.len() > MAX_FILE_BYTES {
            return Err(Error::Validation("staged file exceeds 10 MiB".into()));
        }
        let name = rel.rsplit('/').next().unwrap_or("staged").to_string();
        let parent_rel = rel.rfind('/').map(|i| &rel[..i]).unwrap_or("").to_string();
        let parent_id = dir_ids.get(&parent_rel).copied().ok_or_else(|| {
            Error::Validation("staged parent directory unknown".into())
        })?;
        let stored = orbit_agent_runtime::attachments::upload(
            pool,
            artifact_root,
            scope,
            &name,
            "application/octet-stream",
            &bytes,
        )
        .await?;
        let new_id: Uuid = stored
            .get("id")
            .and_then(|v| serde_json::from_value(v.clone()).ok())
            .ok_or_else(|| Error::Unavailable("upload identity unavailable".into()))?;
        let created =
            create_unique(pool, scope, parent_id, &name, EntryKind::File, Some(new_id)).await?;
        outcome.created.push(created.id);
    }
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn staging_bounds_are_sane() {
        assert!(MAX_STAGED_FILES > 0);
        assert!(MAX_STAGE_BYTES >= 10 * 1024 * 1024);
        assert!(MAX_NEW_FILES > 0);
    }
}
